CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL UNIQUE,password_hash text NOT NULL,display_name text NOT NULL,role text NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS identities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,provider text NOT NULL,provider_subject text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider,provider_subject));
CREATE TABLE IF NOT EXISTS dhan_consents(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL,consumed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS dhan_connections(user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,client_id text NOT NULL,encrypted_access_token text NOT NULL,token_iv text NOT NULL,token_tag text NOT NULL,expires_at timestamptz,connected_at timestamptz NOT NULL DEFAULT now(),last_verified_at timestamptz);
CREATE TABLE IF NOT EXISTS instruments(id text PRIMARY KEY,symbol text NOT NULL,name text NOT NULL,exchange text NOT NULL,sector text,active boolean NOT NULL DEFAULT true,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS dhan_instruments(instrument_id text PRIMARY KEY REFERENCES instruments(id),security_id text NOT NULL,exchange_segment text NOT NULL DEFAULT 'NSE_EQ',synced_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS watchlist_items(user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,instrument_id text NOT NULL REFERENCES instruments(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,instrument_id));
CREATE TABLE IF NOT EXISTS paper_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,name text NOT NULL DEFAULT 'Paper account',starting_cash numeric(18,2) NOT NULL,cash numeric(18,2) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS paper_positions(account_id uuid NOT NULL REFERENCES paper_accounts(id) ON DELETE CASCADE,instrument_id text NOT NULL REFERENCES instruments(id),quantity integer NOT NULL CHECK(quantity>0),avg_price numeric(18,4) NOT NULL,PRIMARY KEY(account_id,instrument_id));
CREATE TABLE IF NOT EXISTS paper_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),client_order_id text UNIQUE,account_id uuid NOT NULL REFERENCES paper_accounts(id),instrument_id text NOT NULL REFERENCES instruments(id),side text NOT NULL CHECK(side IN ('BUY','SELL')),quantity integer NOT NULL CHECK(quantity>0),order_type text NOT NULL CHECK(order_type IN ('MARKET','LIMIT')),status text NOT NULL,requested_price numeric(18,4),fill_price numeric(18,4),fees numeric(18,2) NOT NULL DEFAULT 0,slippage_bps numeric(8,2) NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS paper_orders_client_order_id_uidx ON paper_orders(client_order_id) WHERE client_order_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS paper_fills(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL UNIQUE REFERENCES paper_orders(id),instrument_id text NOT NULL REFERENCES instruments(id),quantity integer NOT NULL,fill_price numeric(18,4) NOT NULL,fees numeric(18,2) NOT NULL,slippage_bps numeric(8,2) NOT NULL,filled_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS paper_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES paper_accounts(id),order_id uuid NOT NULL REFERENCES paper_orders(id),entry_type text NOT NULL,amount numeric(18,2) NOT NULL,cash_after numeric(18,2) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid REFERENCES users(id),event_type text NOT NULL,correlation_id text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS forecasts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),instrument_id text NOT NULL REFERENCES instruments(id),as_of timestamptz NOT NULL,horizon_minutes integer NOT NULL,probability_up numeric(5,4) NOT NULL,expected_return_bps numeric(10,2),interval_low_bps numeric(10,2),interval_high_bps numeric(10,2),model_version text NOT NULL,source text NOT NULL);
CREATE TABLE IF NOT EXISTS feature_flags(key text PRIMARY KEY,enabled boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS risk_policies(user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,max_positions integer NOT NULL DEFAULT 5,daily_loss_pct numeric(5,2) NOT NULL DEFAULT 2,max_deploy_pct numeric(5,2) NOT NULL DEFAULT 60);
CREATE TABLE IF NOT EXISTS price_alerts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,instrument_id text NOT NULL REFERENCES instruments(id),condition text NOT NULL CHECK(condition IN ('ABOVE','BELOW')),target_price numeric(18,4) NOT NULL,status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','TRIGGERED','DISMISSED')),created_at timestamptz NOT NULL DEFAULT now(),triggered_at timestamptz);
CREATE TABLE IF NOT EXISTS backtest_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,instrument_id text NOT NULL REFERENCES instruments(id),strategy text NOT NULL,parameters jsonb NOT NULL,result jsonb NOT NULL,source text NOT NULL DEFAULT 'DEMO_DATA',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS global_events(id text PRIMARY KEY,category text NOT NULL,title text NOT NULL,source text NOT NULL,published_at timestamptz,first_seen_at timestamptz NOT NULL DEFAULT now(),impact text NOT NULL,sentiment text NOT NULL,details text NOT NULL,source_status text NOT NULL DEFAULT 'SAMPLE');
